 292	 private <E> E mapResultSetToEntity(ResultSet resultSet, Class<E> clazz) throws SQLException {
 293	 try {
 294	 E entity = clazz.getDeclaredConstructor().newInstance();
 295	 Field[] fields = clazz.getDeclaredFields();
 296	
 297	 for(Field field : fields) {
 298	 // TODO: refactor
 299	 if(!field.getName().equals("id") && !field.getName().equals("collections") && !field.getName().equals("audiobooks")) {
 300	 field.setAccessible(true);
 301	 Object value = resultSet.getObject(camelCaseToSnakeCase(field.getName()));
 302	 if(value != null) {
 303	 field.set(entity, convertValue(value, field.getType()));
 304	 }
 305	 }
 306	 }
 307	
 308	 return entity;
 309	 } catch (Exception e) {
 310	 throw new SQLException("Не вдалося зіставити ResultSet із сутністю", e);
