```java
public class RelationshipManager {
 private final Connection connection;

 public RelationshipManager(Connection connection) {
 this.connection = connection;
 }

 public void saveRelationship(Object entity1, Object entity2, String tableName, 
 String entity1Field, String entity2Field) throws SQLException {
 try {
 Class<?> entity1Class = entity1.getClass();
 Class<?> entity2Class = entity2.getClass();

 Field idField1 = entity1Class.getDeclaredField("id");
 Field idField2 = entity2Class.getDeclaredField("id");

 idField1.setAccessible(true);
 idField2.setAccessible(true);

 Object id1 = idField1.get(entity1);
 Object id2 = idField2.get(entity2);

 String sql = String.format("INSERT INTO %s (%s, %s) VALUES (?, ?)", 
 tableName, entity1Field, entity2Field);

 try (var statement = connection.prepareStatement(sql)) {
 statement.setObject(1, id1);
 statement.setObject(2, id2);
 statement.executeUpdate();
 }
 } catch (Exception e) {
 throw new SQLException("Не вдалося зберегти зв'язок", e);
 }
 }

 public void removeRelationship(Object entity1, Object entity2, String tableName, 
 String entity1Field, String entity2Field) throws SQLException {
 try {
 Class<?> entity1Class = entity1.getClass();
 Class<?> entity2Class = entity2.getClass();

 Field idField1 = entity1Class.getDeclaredField("id");
 Field idField2 = entity2Class.getDeclaredField("id");

 idField1.setAccessible(true);
 idField2.setAccessible(true);

 Object id1 = idField1.get(entity1);
 Object id2 = idField2.get(entity2);

 String sql = String.format("DELETE FROM %s WHERE %s = ? AND %s = ?", 
 tableName, entity1Field, entity2Field);

 try (var statement = connection.prepareStatement(sql)) {
 statement.setObject(1, id1);
 statement.setObject(2, id2);
 statement.executeUpdate();
 }
 } catch (Exception e) {
 throw new SQLException("Не вдалося видалити зв'язок", e);
 }
 }
}
