 205	 private <E> E mapResultSetToEntity(ResultSet resultSet, Class<E> clazz) throws SQLException {
 206	 try {
 207	 E entity = clazz.getDeclaredConstructor().newInstance();
 208	 Field[] fields = clazz.getDeclaredFields();
 209	
 210	 // Спочатку встановлюємо ID
 211	 try {
 212	 Field idField = clazz.getDeclaredField("id");
 213	 idField.setAccessible(true);
 214	 Object idValue = resultSet.getObject("id");
 215	 if (idValue != null) {
 216	 idField.set(entity, convertValue(idValue, idField.getType()));
 217	 }
 218	 } catch (NoSuchFieldException e) {
 219	 // Ігноруємо, якщо поле id не існує
 220	 }
 221	
 222	 // Встановлюємо інші поля
 223	 for(Field field : fields) {
 224	 if(!field.getName().equals("id") && !field.getName().equals("collections") && !field.getName().equals("audiobooks")) {
 225	 field.setAccessible(true);
 226	 String columnName = camelCaseToSnakeCase(field.getName());
 227	 try {
 228	 Object value = resultSet.getObject(columnName);
 229	 if(value != null) {
 230	 field.set(entity, convertValue(value, field.getType()));
 231	 }
 232	 } catch (SQLException e) {
 233	 // Ігноруємо, якщо колонка не існує
 234	 }
 235	 }
 236	 }
 237	
 238	 return entity;
 239	 } catch (Exception e) {
 240	 throw new SQLException("Не вдалося зіставити ResultSet із сутністю", e);
 241	 }
 242	 }
 243	
 244	 private Object convertValue(Object value, Class<?> targetType) {
 245	 if(value == null && !targetType.isPrimitive()) {
 246	 return null;
 247	 }
 248	
 249	 switch (targetType.getName()) {
 250	 case "java.lang.String":
 251	 return value.toString();
 252	 case "java.util.UUID":
 253	 if(value instanceof String) {
 254	 return UUID.fromString((String) value);
 255	 }
 256	 return value;
 257	 case "java.lang.Integer":
 258	 case "int":
 259	 if(value instanceof Number) {
 260	 return ((Number) value).intValue();
 261	 }
 262	 return value;
 263	 case "java.time.LocalDateTime":
 264	 if(value instanceof Timestamp) {
 265	 return ((Timestamp) value).toLocalDateTime();
 266	 }
 267	 return null;
 268	 case "FileFormat":
 269	 if(value instanceof String) {
 270	 return FileFormat.valueOf((String) value);
 271	 }
 272	 return value;
 273	 default:
 274	 return value;
 275	 }
 276	 }
 277	
 278	 public static String camelCaseToSnakeCase(String input) {
 279	 if (input == null || input.isEmpty()) {
 280	 return input;
 281	 }
 282	 return input.replaceAll("([a-z])([A-Z]+)", "$1_$2").toLowerCase();
 283	 }
 284	
 285	 public static String snakeCaseToCamelCase(String input) {
 286	 if (input == null || input.isEmpty()) {
 287	 return input;
 288	 }
 289	 StringBuilder result = new StringBuilder();
 290	 boolean toUpperCase = false;
 291	 for (char ch : input.toCharArray()) {
 292	 if (ch == '_') {
 293	 toUpperCase = true;
 294	 } else {
 295	 result.append(toUpperCase ? Character.toUpperCase(ch) : ch);
 296	 toUpperCase = false;
 297	 }
 298	 }
 299	 return result.toString();
 300	 }
 301	}
