2\u0438\u0439 \u0435\u043a\u0437\u0435\u043c\u043f\u043b\u044f\u0440 Unit of Work.\n * \n * @param connection \u0437'\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n */\n public UnitOfWorkImpl(Connection connection) {\n this.connection = connection;\n \n // \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0457\u0432 \u0437 \u044f\u0432\u043d\u0438\u043c \u0432\u0438\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044f\u043c \u043d\u0430\u0437\u0432 \u0442\u0430\u0431\u043b\u0438\u0446\u044c\n this.audiobooks = new GenericRepository<>(connection, Audiobook.class, \"audiobooks\");\n this.authors = new GenericRepository<>(connection, Author.class, \"authors\");\n this.genres = new GenericRepository<>(connection, Genre.class, \"genres\");\n this.users = new GenericRepository<>(connection, User.class, \"users\");\n this.collections = new GenericRepository<>(connection, Collection.class, \"collections\");\n this.audiobookFiles = new GenericRepository<>(connection, AudiobookFIle.class, \"audiobook_files\");\n this.listeningProgress = new GenericRepository<>(connection, ListeningProgress.class, \"listening_progress\");\n }\n \n @Override\n public GenericRepository<Audiobook, UUID> getAudiobooks() {\n return audiobooks;\n }\n \n @Override\n public GenericRepository<Author, UUID> getAuthors() {\n return authors;\n }\n \n @Override\n public GenericRepository<Genre, UUID> getGenres() {\n return genres;\n }\n \n @Override\n public GenericRepository<User, UUID> getUsers() {\n return users;\n }\n \n @Override\n public GenericRepository<Collection, UUID> getCollections() {\n return collections;\n }\n \n @Override\n public GenericRepository<AudiobookFIle, UUID> getAudiobookFiles() {\n return audiobookFiles;\n }\n \n @Override\n public GenericRepository<ListeningProgress, UUID> getListeningProgress() {\n return listeningProgress;\n }\n \n @Override\n public void beginTransaction() throws SQLException {\n connection.setAutoCommit(false);\n }\n \n @Override\n public void commitTransaction() throws SQLException {\n connection.commit();\n connection.setAutoCommit(true);\n }\n \n @Override\n public void rollbackTransaction() throws SQLException {\n connection.rollback();\n connection.setAutoCommit(true);\n }\n \n @Override\n public void close() throws Exception {\n if (connection != null && !connection.isClosed()) {\n connection.close();\n }\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Тепер створимо реалізацію інтерфейсу UnitOfWork з типізованими репозиторіями:
