 233	 private T mapResultSetToEntity(ResultSet rs) throws SQLException {
 234	 try {
 235	 T entity = entityClass.getDeclaredConstructor().newInstance();
 236	 Field[] fields = entityClass.getDeclaredFields();
 237	
 238	 for (Field field : fields) {
 239	 field.setAccessible(true);
 240	 Object value = rs.getObject(field.getName());
 241	 if (value != null) {
 242	 field.set(entity, convertValue(value, field.getType()));
 243	 }
 244	 }
 245	 return entity;
 246	 } catch (Exception e) {
 247	 throw new SQLException("Не вдалося зіставити ResultSet із сутністю", e);
 248	 }
 249	 }
