import java.sql.Connection;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Реалізація патерну Unit of Work для управління транзакціями та змінами сутностей.
 * Відстежує нові, оновлені та видалені сутності, синхронізуючи їх із базою даних у межах однієї транзакції.
 * Дозволяє налаштувати назви таблиць для репозиторіїв, подібно до Entity Framework Core.
 */
public class UnitOfWork implements AutoCloseable {
 private final Connection connection;
 private final Map<Class<?>, GenericRepository<?, ?>> repositories;
 private final Map<Class<?>, String> tableNames;
 private final List<Object> newEntities;
 private final List<Object> updatedEntities;
 private final List<Object> deletedEntities;

 /**
 * Конструктор Unit of Work.
 *
 * @param connection З'єднання з базою даних
 */
 public UnitOfWork(Connection connection) {
 this.connection = connection;
 this.repositories = new HashMap<>();
 this.tableNames = new HashMap<>();
 this.newEntities = new ArrayList<>();
 this.updatedEntities = new ArrayList<>();
 this.deletedEntities = new ArrayList<>();
 }

 /**
 * Реєстрація назви таблиці для певного типу сутності.
 *
 * @param entityClass Клас сутності
 * @param tableName Назва таблиці в базі даних
 */
 public void registerTableName(Class<?> entityClass, String tableName) {
 tableNames.put(entityClass, tableName);
 }

 /**
 * Отримання репозиторію для певного типу сутності.
 *
 * @param entityClass Клас сутності
 * @param <T> Тип сутності
 * @param <ID> Тип ідентифікатора
 * @return Репозиторій для роботи з сутністю
 */
 public <T, ID> GenericRepository<T, ID> getRepository(Class<T> entityClass) {
 return (GenericRepository<T, ID>) repositories.computeIfAbsent(entityClass, k -> {
 String tableName = tableNames.getOrDefault(entityClass, entityClass.getSimpleName().toLowerCase());
 return new GenericRepository<>(connection, entityClass, tableName);
 });
 }

 /**
 * Реєстрація нової сутності для збереження.
 *
 * @param entity Сутність для збереження
 */
 public void registerNew(Object entity) {
 newEntities.add(entity);
 }

 /**
 * Реєстрація сутності для оновлення.
 *
 * @param entity Сутність для оновлення
 */
 public void registerUpdated(Object entity) {
 updatedEntities.add(entity);
 }

 /**
 * Реєстрація сутності для видалення.
 *
 * @param entity Сутність для видалення
 */
 public void registerDeleted(Object entity) {
 deletedEntities.add(entity);
 }

 /**
 * Виконання всіх зареєстрованих змін у базі даних у межах однієї транзакції.
 *
 * @throws SQLException У разі помилки доступу до бази даних
 * @throws IllegalAccessException У разі проблем із доступом до полів сутності
 */
 public void commit() throws SQLException, IllegalAccessException {
 try {
 connection.setAutoCommit(false);

 for (Object entity : newEntities) {
 Class<?> entityClass = entity.getClass();
 GenericRepository<Object, Object> repo = (GenericRepository<Object, Object>) getRepository(entityClass);
 repo.save(entity);
 }

 for (Object entity : updatedEntities) {
 Class<?> entityClass = entity.getClass();
 GenericRepository<Object, Object> repo = (GenericRepository<Object, Object>) getRepository(entityClass);
 Object id = entityClass.getDeclaredField("id").get(entity);
 repo.update(id, entity);
 }

 for (Object entity : deletedEntities) {
 Class<?> entityClass = entity.getClass();
 GenericRepository<Object, Object> repo = (GenericRepository<Object, Object>) getRepository(entityClass);
 Object id = entityClass.getDeclaredField("id").get(entity);
 repo.delete(id);
 }

 connection.commit();
 clear();
 } catch (Exception e) {
 connection.rollback();
 throw new SQLException("Не вдалося виконати транзакцію", e);
 } finally {
 connection.setAutoCommit(true);
 }
 }

 /**
 * Очищення списків зареєстрованих сутностей.
 */
 private void clear() {
 newEntities.clear();
 updatedEntities.clear();
 deletedEntities.clear();
 }

 /**
 * Закриття з'єднання з базою даних.
 *
 * @throws SQLException У разі помилки при закритті з'єднання
 */
 @Override
 public void close() throws SQLException {
 if (!connection.isClosed()) {
 connection.close();
 }
 }
}

