import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Пул з'єднань для управління JDBC-з'єднаннями з базою даних.
 * Забезпечує потокобезпечне отримання та повернення з'єднань із підтримкою обмеження максимальної кількості з'єднань.
 */
public class ConnectionPool {
 private static volatile ConnectionPool instance;
 private final BlockingQueue<Connection> availableConnections;
 private final BlockingQueue<Connection> usedConnections;
 private final String url;
 private final String user;
 private final String password;
 private final int maxConnections;
 private final AtomicBoolean isInitialized = new AtomicBoolean(false);

 /**
 * Приватний конструктор для ініціалізації пулу з'єднань.
 *
 * @param url URL бази даних
 * @param user Ім'я користувача
 * @param password Пароль
 * @param maxConnections Максимальна кількість з'єднань
 */
 private ConnectionPool(String url, String user, String password, int maxConnections) {
 this.url = url;
 this.user = user;
 this.password = password;
 this.maxConnections = maxConnections;
 this.availableConnections = new ArrayBlockingQueue<>(maxConnections);
 this.usedConnections = new ArrayBlockingQueue<>(maxConnections);
 initializePool();
 }

 /**
 * Отримання єдиного екземпляра пулу з'єднань (патерн Singleton).
 *
 * @param url URL бази даних
 * @param user Ім'я користувача
 * @param password Пароль
 * @param maxConnections Максимальна кількість з'єднань
 * @return Екземпляр пулу з'єднань
 */
 public static ConnectionPool getInstance(String url, String user, String password, int maxConnections) {
 if (instance == null) {
 synchronized (ConnectionPool.class) {
 if (instance == null) {
 instance = new ConnectionPool(url, user, password, maxConnections);
 }
 }
 }
 return instance;
 }

 /**
 * Ініціалізація пулу з'єднань.
 */
 private void initializePool() {
 if (isInitialized.compareAndSet(false, true)) {
 for (int i = 0; i < maxConnections; i++) {
 try {
 availableConnections.add(createConnection());
 } catch (SQLException e) {
 throw new RuntimeException("Не вдалося ініціалізувати пул з'єднань", e);
 }
 }
 }
 }

 /**
 * Створення нового з'єднання з базою даних.
 *
 * @return Нове з'єднання
 * @throws SQLException У разі помилки створення з'єднання
 */
 private Connection createConnection() throws SQLException {
 return DriverManager.getConnection(url, user, password);
 }

 /**
 * Отримання з'єднання з пулу.
 *
 * @return Доступне з'єднання
 * @throws SQLException Якщо немає доступних з'єднань
 */
 public Connection getConnection() throws SQLException {
 Connection connection;
 try {
 connection = availableConnections.take(); // Блокується, якщо пул порожній
 if (connection.isClosed()) {
 connection = createConnection();
 }
 } catch (InterruptedException e) {
 Thread.currentThread().interrupt();
 throw new SQLException("Перервано очікування з'єднання", e);
 }

 synchronized (this) {
 if (usedConnections.size() >= maxConnections) {
 throw new SQLException("Досягнуто максимальної кількості з'єднань");
 }
 usedConnections.add(connection);
 }
 return connection;
 }

 /**
 * Повернення з'єднання до пулу.
 *
 * @param connection З'єднання для повернення
 */
 public void releaseConnection(Connection connection) {
 if (connection != null) {
 synchronized (this) {
 usedConnections.remove(connection);
 }
 try {
 if (!connection.isClosed()) {
 availableConnections.offer(connection);
 }
 } catch (SQLException e) {
 // Логування помилки
 }
 }
 }

 /**
 * Закриття всіх з'єднань і очищення пулу.
 *
 * @throws SQLException У разі помилки закриття з'єднань
 */
 public void shutdown() throws SQLException {
 synchronized (this) {
 for (Connection conn : availableConnections) {
 conn.close();
 }
 for (Connection conn : usedConnections) {
 conn.close();
 }
 availableConnections.clear();
 usedConnections.clear();
 isInitialized.set(false);
 instance = null;
 }
 }
}



