","workspace_file_chunks":[]},{"status":"success","request_id":"460dc797-0091-439c-b438-53ceeae3efb1","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_vrtx_01CbfbioQG1ki7TY4FyT8N96","tool_name":"save-file","input_json":"{"file_path": "src/main/java/com/arakviel/infrastructure/persistence/Example.java", "file_content": "package com.arakviel.infrastructure.persistence;\n\nimport com.arakviel.domain.enitites.Audiobook;\nimport com.arakviel.domain.enitites.Author;\nimport com.arakviel.domain.enitites.User;\n\nimport java.sql.Connection;\nimport java.sql.SQLException;\nimport java.util.UUID;\n\n/**\n * \u041f\u0440\u0438\u043a\u043b\u0430\u0434 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u0430\u043d\u043d\u044f UnitOfWork \u0442\u0430 ConnectionPool.\n */\npublic class Example {\n \n public static void main(String[] args) {\n // \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f \u043f\u0443\u043b\u0443 \u0437'\u0454\u0434\u043d\u0430\u043d\u044c\n ConnectionPool connectionPool = ConnectionPool.getInstance(\n \"jdbc:h2:mem:audiobooksdb\", \"sa\", \"\", 10);\n \n try {\n // \u041e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u0437'\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0437 \u043f\u0443\u043b\u0443\n Connection connection = connectionPool.getConnection();\n \n // \u0421\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f UnitOfWork\n try (UnitOfWork unitOfWork = new UnitOfWork(connection)) {\n // \u0421\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n User user = new User();\n user.setId(UUID.randomUUID());\n user.setUsername(\"john_doe\");\n user.setPasswordHash(\"hashed_password\");\n user.setEmail(\"john.doe@example.com\");\n \n // \u0420\u0435\u0454\u0441\u0442\u0440\u0430\u0446\u0456\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0434\u043b\u044f \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f\n unitOfWork.registerNew(user);\n \n // \u0421\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u0430\u0432\u0442\u043e\u0440\u0430\n Author author = new Author();\n author.setId(UUID.randomUUID());\n author.setFirstName(\"Stephen\");\n author.setLastName(\"King\");\n author.setBio(\"Famous horror writer\");\n \n // \u0420\u0435\u0454\u0441\u0442\u0440\u0430\u0446\u0456\u044f \u0430\u0432\u0442\u043e\u0440\u0430 \u0434\u043b\u044f \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f\n unitOfWork.registerNew(author);\n \n // \u0421\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043d\u043e\u0432\u043e\u0457 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n Audiobook audiobook = new Audiobook();\n audiobook.setId(UUID.randomUUID());\n audiobook.setAuthorId(author.getId());\n audiobook.setTitle(\"The Shining\");\n audiobook.setDuration(720);\n audiobook.setReleaseYear(2020);\n audiobook.setDescription(\"A horror novel about a family in an isolated hotel\");\n \n // \u0420\u0435\u0454\u0441\u0442\u0440\u0430\u0446\u0456\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u0434\u043b\u044f \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f\n unitOfWork.registerNew(audiobook);\n \n // \u0412\u0438\u043a\u043e\u043d\u0430\u043d\u043d\u044f \u0432\u0441\u0456\u0445 \u0437\u043c\u0456\u043d \u0443 \u043c\u0435\u0436\u0430\u0445 \u043e\u0434\u043d\u0456\u0454\u0457 \u0442\u0440\u0430\u043d\u0437\u0430\u043a\u0446\u0456\u0457\n unitOfWork.commit();\n \n // \u041f\u043e\u0448\u0443\u043a \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0437\u0430 \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440\u043e\u043c\n User foundUser = unitOfWork.getUsers().findById(user.getId()).orElse(null);\n if (foundUser != null) {\n System.out.println(\"\u0417\u043d\u0430\u0439\u0434\u0435\u043d\u043e \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430: \" + foundUser.getUsername());\n }\n \n // \u041e\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n if (foundUser != null) {\n foundUser.setEmail(\"john.updated@example.com\");\n unitOfWork.registerUpdated(foundUser);\n unitOfWork.commit();\n }\n \n // \u0412\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n unitOfWork.registerDeleted(foundUser);\n unitOfWork.commit();\n }\n \n // \u041f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f \u0437'\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0434\u043e \u043f\u0443\u043b\u0443\n connectionPool.releaseConnection(connection);\n \n } catch (SQLException | IllegalAccessException e) {\n e.printStackTrace();\n } finally {\n try {\n // \u0417\u0430\u043a\u0440\u0438\u0442\u0442\u044f \u043f\u0443\u043b\u0443 \u0437'\u0454\u0434\u043d\u0430\u043d\u044c\n connectionPool.shutdown();\n } catch (SQLException e) {\n e.printStackTrace();\n }\n }\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Тепер створю приклад використання `UnitOfWork` та `ConnectionPool`:
