 11	/**
 12	 * Реалізація патерну Unit of Work для управління транзакціями та змінами сутностей.
 13	 * Відстежує нові, оновлені та видалені сутності, синхронізуючи їх із базою даних у межах однієї транзакції.
 14	 * Дозволяє налаштувати назви таблиць для репозиторіїв, подібно до Entity Framework Core.
 15	 */
 16	public class UnitOfWork implements AutoCloseable {
 17	 private final Connection connection;
 18	 private final Map<Class<?>, GenericRepository<?, ?>> repositories;
 19	 private final List<Object> newEntities;
 20	 private final List<Object> updatedEntities;
 21	 private final List<Object> deletedEntities;
 22	
 23	 /**
 24	 * Конструктор Unit of Work.
 25	 *
 26	 * @param connection З'єднання з базою даних
 27	 */
 28	 public UnitOfWork(Connection connection) {
 29	 this.connection = connection;
 30	 this.repositories = new HashMap<>();
 31	 this.newEntities = new ArrayList<>();
 32	 this.updatedEntities = new ArrayList<>();
 33	 this.deletedEntities = new ArrayList<>();
 34	 }
 35	
 36	 /**
 37	 * Реєстрація репозиторію для певного типу сутності.
 38	 *
 39	 * @param entityClass Клас сутності
 40	 * @param repository Репозиторій для роботи з сутністю
 41	 * @param <T> Тип сутності
 42	 * @param <ID> Тип ідентифікатора
 43	 */
 44	 public <T, ID> void registerRepository(Class<T> entityClass, GenericRepository<T, ID> repository) {
 45	 repositories.put(entityClass, repository);
 46	 }
 47	
 48	 /**
 49	 * Отримання репозиторію для певного типу сутності.
 50	 *
 51	 * @param entityClass Клас сутності
 52	 * @param <T> Тип сутності
 53	 * @param <ID> Тип ідентифікатора
 54	 * @return Репозиторій для роботи з сутністю
 55	 */
 56	 @SuppressWarnings("unchecked")
 57	 public <T, ID> GenericRepository<T, ID> getRepository(Class<T> entityClass) {
 58	 return (GenericRepository<T, ID>) repositories.get(entityClass);
 59	 }
 60	
 61	 /**
 62	 * Реєстрація нової сутності для збереження.
 63	 *
 64	 * @param entity Сутність для збереження
 65	 */
 66	 public void registerNew(Object entity) {
 67	 newEntities.add(entity);
 68	 }
 69	
 70	 /**
 71	 * Реєстрація сутності для оновлення.
 72	 *
 73	 * @param entity Сутність для оновлення
 74	 */
 75	 public void registerUpdated(Object entity) {
 76	 updatedEntities.add(entity);
 77	 }
 78	
 79	 /**
 80	 * Реєстрація сутності для видалення.
 81	 *
 82	 * @param entity Сутність для видалення
 83	 */
 84	 public void registerDeleted(Object entity) {
 85	 deletedEntities.add(entity);
 86	 }
