 88	 /**
 89	 * Виконання всіх зареєстрованих змін у базі даних у межах однієї транзакції.
 90	 *
 91	 * @throws SQLException У разі помилки доступу до бази даних
 92	 * @throws IllegalAccessException У разі проблем із доступом до полів сутності
 93	 */
 94	 @SuppressWarnings("unchecked")
 95	 public void commit() throws SQLException, IllegalAccessException {
 96	 try {
 97	 connection.setAutoCommit(false);
 98	
 99	 // Збереження нових сутностей
 100	 for (Object entity : newEntities) {
 101	 processEntity(entity, OperationType.SAVE);
 102	 }
 103	
 104	 // Оновлення існуючих сутностей
 105	 for (Object entity : updatedEntities) {
 106	 processEntity(entity, OperationType.UPDATE);
 107	 }
 108	
 109	 // Видалення сутностей
 110	 for (Object entity : deletedEntities) {
 111	 processEntity(entity, OperationType.DELETE);
 112	 }
 113	
 114	 connection.commit();
 115	 clear();
 116	 } catch (Exception e) {
 117	 connection.rollback();
 118	 throw new SQLException("Не вдалося виконати транзакцію", e);
 119	 } finally {
 120	 connection.setAutoCommit(true);
 121	 }
 122	 }
 123	
 124	 /**
 125	 * Типи операцій з сутностями.
 126	 */
 127	 private enum OperationType {
 128	 SAVE, UPDATE, DELETE
 129	 }
 130	
 131	 /**
 132	 * Обробка сутності відповідно до типу операції.
 133	 *
 134	 * @param entity Сутність для обробки
 135	 * @param operationType Тип операції
 136	 * @throws SQLException У разі помилки доступу до бази даних
 137	 * @throws IllegalAccessException У разі проблем із доступом до полів сутності
 138	 */
 139	 @SuppressWarnings("unchecked")
 140	 private <T> void processEntity(Object entity, OperationType operationType) throws SQLException, IllegalAccessException, NoSuchFieldException {
 141	 Class<T> entityClass = (Class<T>) entity.getClass();
 142	 GenericRepository<T, Object> repo = getRepository(entityClass);
 143	
 144	 if (repo == null) {
 145	 throw new IllegalArgumentException("Непідтримуваний тип сутності: " + entityClass.getName());
 146	 }
 147	
 148	 T typedEntity = (T) entity;
 149	
 150	 switch (operationType) {
 151	 case SAVE:
 152	 repo.save(typedEntity);
 153	 break;
 154	 case UPDATE:
 155	 Object updateId = getEntityId(entity);
 156	 repo.update(updateId, typedEntity);
 157	 break;
 158	 case DELETE:
 159	 Object deleteId = getEntityId(entity);
 160	 repo.delete(deleteId);
 161	 break;
 162	 }
 163	 }
 164	
 165	 /**
 166	 * Отримання ідентифікатора сутності.
 167	 *
 168	 * @param entity Сутність
 169	 * @return Ідентифікатор сутності
 170	 * @throws IllegalAccessException У разі проблем із доступом до полів сутності
 171	 * @throws NoSuchFieldException Якщо поле id не знайдено
 172	 */
 173	 private Object getEntityId(Object entity) throws IllegalAccessException, NoSuchFieldException {
 174	 Field idField = entity.getClass().getDeclaredField("id");
 175	 idField.setAccessible(true);
 176	 return idField.get(entity);
 177	 }
 178	
 179	 /**
 180	 * Очищення списків зареєстрованих сутностей.
 181	 */
 182	 private void clear() {
 183	 newEntities.clear();
 184	 updatedEntities.clear();
 185	 deletedEntities.clear();
 186	 }
 187	
 188	 /**
 189	 * Закриття з'єднання з базою даних.
 190	 *
 191	 * @throws SQLException У разі помилки при закритті з'єднання
 192	 */
 193	 @Override
 194	 public void close() throws SQLException {
 195	 if (!connection.isClosed()) {
 196	 connection.close();
 197	 }
 198	 }
