430\u043d\u0438\u0445, \u044f\u043a\u0449\u043e \u0432\u043e\u043d\u0430 \u0449\u0435 \u043d\u0435 \u0456\u0441\u043d\u0443\u0454.\n * \u0412\u0438\u043a\u043e\u043d\u0443\u0454 SQL-\u0441\u043a\u0440\u0438\u043f\u0442\u0438 \u0434\u043b\u044f \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u044c \u0442\u0430 \u0437\u0430\u043f\u043e\u0432\u043d\u0435\u043d\u043d\u044f \u0457\u0445 \u0434\u0430\u043d\u0438\u043c\u0438.\n */\n public void init() {\n try {\n if (!databaseExists()) {\n createDatabase();\n }\n } catch (SQLException e) {\n throw new RuntimeException(\"\u041f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457 \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445\", e);\n }\n }\n \n /**\n * \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0454, \u0447\u0438 \u0456\u0441\u043d\u0443\u0454 \u0431\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445.\n * \n * @return true, \u044f\u043a\u0449\u043e \u0431\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445 \u0456\u0441\u043d\u0443\u0454, \u0456\u043d\u0430\u043a\u0448\u0435 false\n * @throws SQLException \u0443 \u0440\u0430\u0437\u0456 \u043f\u043e\u043c\u0438\u043b\u043a\u0438 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n */\n private boolean databaseExists() throws SQLException {\n File dbFile = new File(DB_FILE_PATH + \".mv.db\");\n if (dbFile.exists()) {\n try (Connection connection = connectionPool.getConnection()) {\n DatabaseMetaData metaData = connection.getMetaData();\n ResultSet tables = metaData.getTables(null, null, \"AUDIOBOOKS\", null);\n return tables.next(); // \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0454\u043c\u043e, \u0447\u0438 \u0456\u0441\u043d\u0443\u0454 \u0442\u0430\u0431\u043b\u0438\u0446\u044f AUDIOBOOKS\n }\n }\n return false;\n }\n \n /**\n * \u0421\u0442\u0432\u043e\u0440\u044e\u0454 \u0431\u0430\u0437\u0443 \u0434\u0430\u043d\u0438\u0445 \u0442\u0430 \u0437\u0430\u043f\u043e\u0432\u043d\u044e\u0454 \u0457\u0457 \u0434\u0430\u043d\u0438\u043c\u0438.\n * \n * @throws SQLException \u0443 \u0440\u0430\u0437\u0456 \u043f\u043e\u043c\u0438\u043b\u043a\u0438 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n */\n private void createDatabase() throws SQLException {\n try (Connection connection = connectionPool.getConnection()) {\n connection.setAutoCommit(false);\n \n try (Statement statementForDDL = connection.createStatement();\n Statement statementForDML = connection.createStatement()) {\n \n // \u0412\u0438\u043a\u043e\u043d\u0443\u0454\u043c\u043e DDL-\u0441\u043a\u0440\u0438\u043f\u0442 \u0434\u043b\u044f \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u044c\n statementForDDL.execute(getSQL(\"db/ddl_h2.sql\"));\n \n // \u0412\u0438\u043a\u043e\u043d\u0443\u0454\u043c\u043e DML-\u0441\u043a\u0440\u0438\u043f\u0442 \u0434\u043b\u044f \u0437\u0430\u043f\u043e\u0432\u043d\u0435\u043d\u043d\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u044c \u0434\u0430\u043d\u0438\u043c\u0438\n statementForDML.execute(getSQL(\"db/dml_h2.sql\"));\n \n connection.commit();\n System.out.println(\"\u0411\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445 \u0443\u0441\u043f\u0456\u0448\u043d\u043e \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0430\");\n } catch (SQLException e) {\n connection.rollback();\n throw e;\n } finally {\n connection.setAutoCommit(true);\n }\n }\n }\n \n /**\n * \u041e\u0442\u0440\u0438\u043c\u0443\u0454 SQL-\u0441\u043a\u0440\u0438\u043f\u0442 \u0437 \u0440\u0435\u0441\u0443\u0440\u0441\u0456\u0432.\n * \n * @param resourceName \u0456\u043c'\u044f \u0440\u0435\u0441\u0443\u0440\u0441\u0443\n * @return SQL-\u0441\u043a\u0440\u0438\u043f\u0442 \u0443 \u0432\u0438\u0433\u043b\u044f\u0434\u0456 \u0440\u044f\u0434\u043a\u0430\n */\n private String getSQL(final String resourceName) {\n return new BufferedReader(\n new InputStreamReader(\n Objects.requireNonNull(\n getClass().getClassLoader().getResourceAsStream(resourceName))))\n .lines()\n .collect(Collectors.joining(\"\\n\"));\n }\n \n /**\n * \u041f\u043e\u0432\u0435\u0440\u0442\u0430\u0454 URL \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445.\n * \n * @return URL \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445\n */\n public static String getDbUrl() {\n return DB_URL;\n }\n \n /**\n * \u041f\u043e\u0432\u0435\u0440\u0442\u0430\u0454 \u0456\u043c'\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445.\n * \n * @return \u0456\u043c'\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445\n */\n public static String getDbUser() {\n return DB_USER;\n }\n \n /**\n * \u041f\u043e\u0432\u0435\u0440\u0442\u0430\u0454 \u043f\u0430\u0440\u043e\u043b\u044c \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445.\n * \n * @return \u043f\u0430\u0440\u043e\u043b\u044c \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445\n */\n public static String getDbPassword() {\n return DB_PASSWORD;\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Чудово, я бачу, що в директорії `src/main/resources/db` вже є файли `ddl_h2.sql` та `dml_h2.sql`. Тепер я створю клас `DatabaseInitializer` для ініціалізації бази даних H2 при запуску програми.

