pository.findAll().forEach(user -> {\n System.out.println(\"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447: \" + user.getUsername() + \", Email: \" + user.getEmail());\n });\n \n // \u041f\u043e\u0448\u0443\u043a \u0430\u0432\u0442\u043e\u0440\u0456\u0432\n GenericRepository<Author, UUID> authorRepository = unitOfWork.<Author, UUID>getRepository(Author.class);\n authorRepository.findAll().forEach(author -> {\n System.out.println(\"\u0410\u0432\u0442\u043e\u0440: \" + author.getFirstName() + \" \" + author.getLastName());\n });\n \n // \u041f\u043e\u0448\u0443\u043a \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\n GenericRepository<Audiobook, UUID> audiobookRepository = unitOfWork.<Audiobook, UUID>getRepository(Audiobook.class);\n audiobookRepository.findAll().forEach(audiobook -> {\n System.out.println(\"\u0410\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430: \" + audiobook.getTitle() + \", \u0422\u0440\u0438\u0432\u0430\u043b\u0456\u0441\u0442\u044c: \" + audiobook.getDuration() + \" \u0445\u0432\");\n });\n }\n \n // \u0417\u0430\u043a\u0440\u0438\u0442\u0442\u044f \u0437'\u0454\u0434\u043d\u0430\u043d\u044c \u043f\u0440\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u0456 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u0438\n DatabaseManager.shutdown();\n \n } catch (SQLException e) {\n System.err.println(\"\u041f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445: \" + e.getMessage());\n e.printStackTrace();\n }\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Тепер створю клас `Application` для запуску програми:
