GN KEY (user_id)\n REFERENCES users(id) ON DELETE CASCADE,\n\n name VARCHAR(128) NOT NULL,\n CONSTRAINT collections_name_not_empty_check\n CHECK (length(trim(name)) > 0),\n created_at TIMESTAMP\n);\n\n-- 3NF\nCREATE TABLE audiobooks (\n PRIMARY KEY(id),\n id UUID,\n author_id UUID NOT NULL,\n CONSTRAINT audiobooks_author_id_authors_id_fkey\n FOREIGN KEY (author_id)\n REFERENCES authors(id) ON DELETE CASCADE,\n\n genre_id UUID NOT NULL,\n CONSTRAINT audiobooks_genre_id_genres_id_fkey\n FOREIGN KEY (genre_id)\n REFERENCES genres(id) ON DELETE CASCADE,\n\n title VARCHAR(255) NOT NULL,\n duration INTEGER NOT NULL,\n CONSTRAINT audiobooks_duration_positive_check\n CHECK (duration > 0),\n \n release_year INTEGER NOT NULL,\n CONSTRAINT audiobooks_release_year_check\n CHECK (release_year >= 1900 AND release_year <= 2100),\n\n description TEXT,\n cover_image_path VARCHAR(2048)\n);\n\n-- 3NF\nCREATE TABLE audiobook_files (\n PRIMARY KEY(id),\n id UUID,\n audiobook_id UUID NOT NULL,\n CONSTRAINT audiobook_files_audiobook_id_audiobooks_id_fkey\n FOREIGN KEY (audiobook_id)\n REFERENCES audiobooks(id) ON DELETE CASCADE,\n\n file_path VARCHAR(2048) NOT NULL,\n file_format file_format_enum NOT NULL,\n file_size BIGINT NOT NULL,\n CONSTRAINT audiobook_files_file_size_positive_check\n CHECK (file_size > 0),\n\n duration INTEGER NOT NULL,\n CONSTRAINT audiobook_files_duration_positive_check\n CHECK (duration > 0),\n\n bitrate INTEGER NOT NULL,\n CONSTRAINT audiobook_files_bitrate_positive_check\n CHECK (bitrate > 0)\n);\n\n-- \u0417\u0432'\u044f\u0437\u043e\u043a \u0431\u0430\u0433\u0430\u0442\u043e-\u0434\u043e-\u0431\u0430\u0433\u0430\u0442\u044c\u043e\u0445 \u043c\u0456\u0436 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430\u043c\u0438 \u0442\u0430 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044f\u043c\u0438\nCREATE TABLE audiobook_collection (\n PRIMARY KEY(audiobook_id, collection_id),\n audiobook_id UUID,\n CONSTRAINT audiobook_collection_audiobook_id_audiobooks_id_fkey\n FOREIGN KEY (audiobook_id)\n REFERENCES audiobooks(id) ON DELETE CASCADE,\n\n collection_id UUID,\n CONSTRAINT audiobook_collection_collection_id_collections_id_fkey\n FOREIGN KEY (collection_id)\n REFERENCES collections(id) ON DELETE CASCADE\n);\n\n-- 3NF\nCREATE TABLE listening_progress (\n PRIMARY KEY(id),\n id UUID,\n user_id UUID NOT NULL,\n CONSTRAINT listening_progress_user_id_users_id_fkey\n FOREIGN KEY (user_id)\n REFERENCES users(id) ON DELETE CASCADE,\n\n audiobook_id UUID NOT NULL,\n CONSTRAINT listening_progress_audiobook_id_audiobooks_id_fkey\n FOREIGN KEY (audiobook_id)\n REFERENCES audiobooks(id) ON DELETE CASCADE,\n\n position INTEGER NOT NULL,\n CONSTRAINT listening_progress_position_positive_check\n CHECK (position >= 0),\n\n updated_at TIMESTAMP NOT NULL\n);\n\n-- \u0406\u043d\u0434\u0435\u043a\u0441\u0438 \u0434\u043b\u044f \u0437\u043e\u0432\u043d\u0456\u0448\u043d\u0456\u0445 \u043a\u043b\u044e\u0447\u0456\u0432\nCREATE INDEX audiobooks_author_id_idx ON audiobooks(author_id);\nCREATE INDEX audiobooks_genre_id_idx ON audiobooks(genre_id);\nCREATE INDEX collections_user_id_idx ON collections(user_id);\nCREATE INDEX audiobook_files_audiobook_id_idx ON audiobook_files(audiobook_id);\nCREATE INDEX audiobook_collection_audiobook_id_idx ON audiobook_collection(audiobook_id);\nCREATE INDEX audiobook_collection_collection_id_idx ON audiobook_collection(collection_id);\nCREATE INDEX listening_progress_user_id_idx ON listening_progress(user_id);\nCREATE INDEX listening_progress_audiobook_id_idx ON listening_progress(audiobook_id);"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Тепер я розумію проблему. У SQL-файлі є синтаксична помилка в рядку 80, де `ON DELETE CASCADE` знаходиться на окремому рядку. Давайте виправимо цю помилку, створивши новий SQL-файл з виправленим синтаксисом:
