 private void loadRelations(T entity) throws SQLException {
 try {
 Field idField = entityClass.getDeclaredField("id");
 idField.setAccessible(true);
 ID entityId = (ID) idField.get(entity);

 if(entityClass == Audiobook.class) {
 String sql = """
 SELECT c.* FROM collections c
 INNER JOIN audiobook_collection ac ON c.id = ac.collection_id
 WHERE ac.audiobook_id = ?
 """;
 try(var statement = connection.prepareStatement(sql)) {
 statement.setObject(1, entityId);
 try(var resultSet = statement.executeQuery()) {
 List<Collection> collections = new ArrayList<>();
 while(resultSet.next()) {
 Collection collection = mapResultSetToEntity(resultSet, Collection.class);
 collections.add(collection);
 }

 Field collectionsField = entityClass.getDeclaredField("collections");
 collectionsField.setAccessible(true);
 collectionsField.set(entity, collections);
 }
 }
 } else if(entityClass == Collection.class) {
 String sql = """
 SELECT a.* FROM audiobooks a
 INNER JOIN audiobook_collection ac ON audiobook_collection.id = ac.collection_id
 WHERE ac.collection_id = ?
 """;
 try(var statement = connection.prepareStatement(sql)) {
 statement.setObject(1, entityId);
 try(var resultSet = statement.executeQuery()) {
 List<Audiobook> audiobooks = new ArrayList<>();
 while(resultSet.next()) {
 Audiobook audiobook = mapResultSetToEntity(resultSet, Audiobook.class);
 audiobooks.add(audiobook);
 }
 Field audiobooksField = entityClass.getDeclaredField("audiobooks");
 audiobooksField.setAccessible(true);
 audiobooksField.set(entity, audiobooks);
 }
 }
 }

 } catch (IllegalAccessException | NoSuchFieldException e) {
 throw new SQLException("Не вдалося завантажити зв'язки", e);
 }
 }

