 314	 private Object convertValue(Object value, Class<?> targetType) {
 315	 if(value == null && !targetType.isPrimitive()) {
 316	 return null;
 317	 }
 318	
 319	 switch (targetType.getName()) {
 320	 case "java.lang.String":
 321	 return value.toString();
 322	 case "java.util.UUID":
 323	 if(value instanceof String) {
 324	 return UUID.fromString((String) value);
 325	 }
 326	 return value;
 327	 case "java.lang.Integer":
 328	 case "int":
 329	 if(value instanceof Number) {
 330	 return ((Number) value).intValue();
 331	 }
 332	 return value;
 333	 case "java.time.LocalDateTime":
 334	 if(value instanceof Timestamp) {
 335	 return ((Timestamp) value).toLocalDateTime();
 336	 }
 337	 return null;
 338	 case "FileFormat":
 339	 if(value instanceof String) {
 340	 return FileFormat.valueOf((String) value);
 341	 }
 342	 return value;
 343	 default:
 344	 return value;
 345	 }
 346	 }
