 16	public class UnitOfWork implements AutoCloseable {
 17	 private final Connection connection;
 18	 private final Map<Class<?>, GenericRepository<?, ?>> repositories;
 19	 private final List<Object> newEntities;
 20	 private final List<Object> updatedEntities;
 21	 private final List<Object> deletedEntities;
 22	
 23	 /**
