 94	 @SuppressWarnings("unchecked")
 95	 public void commit() throws SQLException, IllegalAccessException {
 96	 try {
 97	 connection.setAutoCommit(false);
 98	
 99	 // Збереження нових сутностей
 100	 for (Object entity : newEntities) {
 101	 processEntity(entity, OperationType.SAVE);
 102	 }
 103	
 104	 // Оновлення існуючих сутностей
 105	 for (Object entity : updatedEntities) {
 106	 processEntity(entity, OperationType.UPDATE);
 107	 }
 108	
 109	 // Видалення сутностей
 110	 for (Object entity : deletedEntities) {
 111	 processEntity(entity, OperationType.DELETE);
 112	 }
 113	
 114	 connection.commit();
 115	 clear();
 116	 } catch (Exception e) {
 117	 connection.rollback();
 118	 throw new SQLException("Не вдалося виконати транзакцію", e);
 119	 } finally {
