 for (Field field : entityClass.getDeclaredFields()) {
 if (field.getName().equals("id")) continue;
 setClause.add(camelCaseToSnakeCase(field.getName()) + " = ?");
 }
 return String.format("UPDATE %s SET %s WHERE id = ?", tableName, setClause);
