 532	 protected Object convertValue(Object value, Class<?> targetType) {
 533	 if (value == null && !targetType.isPrimitive()) {
 534	 return null;
 535	 }
 536	 return switch (targetType.getName()) {
 537	 case "java.lang.String" -> value.toString();
 538	 case "java.util.UUID" -> {
 539	 if (value instanceof UUID) {
 540	 yield value;
 541	 } else if (value instanceof String) {
 542	 try {
 543	 yield UUID.fromString((String) value);
 544	 } catch (IllegalArgumentException e) {
 545	 throw new EntityMappingException("Невірний формат UUID: " + value, e);
 546	 }
 547	 } else {
 548	 throw new EntityMappingException("Неможливо конвертувати " + value.getClass().getName() + " в UUID");
 549	 }
 550	 }
 551	 case "java.lang.Integer", "int" ->
 552	 value instanceof Number ? ((Number) value).intValue() : Integer.parseInt(value.toString());
 553	 case "java.time.LocalDateTime" -> value instanceof Timestamp ? ((Timestamp) value).toLocalDateTime() : null;
 554	 case "com.arakviel.domain.enums.FileFormat" -> {
 555	 if (value instanceof FileFormat) {
