 */
 @Override
 public Optional<ListeningProgress> findByUserIdAndAudiobookId(UUID userId, UUID audiobookId) {
 return findAll(
 (whereClause, params) -> {
 whereClause.add("user_id = ?");
 whereClause.add("audiobook_id = ?");
 params.add(userId);
 params.add(audiobookId);
 },
 null, true, 0, 1
 ).stream().findFirst();
 }
