\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n * @param duration \u0442\u0440\u0438\u0432\u0430\u043b\u0456\u0441\u0442\u044c \u0443 \u0441\u0435\u043a\u0443\u043d\u0434\u0430\u0445\n * @param releaseYear \u0440\u0456\u043a \u0432\u0438\u043f\u0443\u0441\u043a\u0443\n * @param description \u043e\u043f\u0438\u0441\n * @return \u043d\u043e\u0432\u0430 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430\n */\n public static Audiobook create(\n AuthorId authorId,\n GenreId genreId,\n String title,\n int duration,\n int releaseYear,\n String description) {\n \n return new Audiobook(\n AudiobookId.generate(),\n authorId,\n genreId,\n title,\n duration,\n releaseYear,\n description,\n null\n );\n }\n \n /**\n * \u0412\u0456\u0434\u043d\u043e\u0432\u043b\u044e\u0454 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443 \u0437 \u0456\u0441\u043d\u0443\u044e\u0447\u0438\u0445 \u0434\u0430\u043d\u0438\u0445.\n *\n * @param id \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440\n * @param authorId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0430\u0432\u0442\u043e\u0440\u0430\n * @param genreId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0436\u0430\u043d\u0440\u0443\n * @param title \u043d\u0430\u0437\u0432\u0430\n * @param duration \u0442\u0440\u0438\u0432\u0430\u043b\u0456\u0441\u0442\u044c\n * @param releaseYear \u0440\u0456\u043a \u0432\u0438\u043f\u0443\u0441\u043a\u0443\n * @param description \u043e\u043f\u0438\u0441\n * @param coverImagePath \u0448\u043b\u044f\u0445 \u0434\u043e \u043e\u0431\u043a\u043b\u0430\u0434\u0438\u043d\u043a\u0438\n * @return \u0432\u0456\u0434\u043d\u043e\u0432\u043b\u0435\u043d\u0430 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430\n */\n public static Audiobook restore(\n UUID id,\n UUID authorId,\n UUID genreId,\n String title,\n int duration,\n int releaseYear,\n String description,\n String coverImagePath) {\n \n return new Audiobook(\n new AudiobookId(id),\n new AuthorId(authorId),\n new GenreId(genreId),\n title,\n duration,\n releaseYear,\n description,\n coverImagePath\n );\n }\n \n private Audiobook(\n AudiobookId id,\n AuthorId authorId,\n GenreId genreId,\n String title,\n int duration,\n int releaseYear,\n String description,\n String coverImagePath) {\n \n validateTitle(title);\n validateDuration(duration);\n validateReleaseYear(releaseYear);\n \n this.id = id;\n this.authorId = authorId;\n this.genreId = genreId;\n this.title = title;\n this.duration = duration;\n this.releaseYear = releaseYear;\n this.description = description;\n this.coverImagePath = coverImagePath;\n }\n \n /**\n * \u041e\u043d\u043e\u0432\u043b\u044e\u0454 \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044e \u043f\u0440\u043e \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443.\n *\n * @param title \u043d\u043e\u0432\u0430 \u043d\u0430\u0437\u0432\u0430\n * @param duration \u043d\u043e\u0432\u0430 \u0442\u0440\u0438\u0432\u0430\u043b\u0456\u0441\u0442\u044c\n * @param releaseYear \u043d\u043e\u0432\u0438\u0439 \u0440\u0456\u043a \u0432\u0438\u043f\u0443\u0441\u043a\u0443\n * @param description \u043d\u043e\u0432\u0438\u0439 \u043e\u043f\u0438\u0441\n * @return \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u0430 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430\n */\n public Audiobook updateInfo(String title, int duration, int releaseYear, String description) {\n validateTitle(title);\n validateDuration(duration);\n validateReleaseYear(releaseYear);\n \n this.title = title;\n this.duration = duration;\n this.releaseYear = releaseYear;\n this.description = description;\n \n return this;\n }\n \n /**\n * \u041e\u043d\u043e\u0432\u043b\u044e\u0454 \u043e\u0431\u043a\u043b\u0430\u0434\u0438\u043d\u043a\u0443 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438.\n *\n * @param coverImagePath \u0448\u043b\u044f\u0445 \u0434\u043e \u043d\u043e\u0432\u043e\u0457 \u043e\u0431\u043a\u043b\u0430\u0434\u0438\u043d\u043a\u0438\n * @return \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u0430 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430\n */\n public Audiobook updateCoverImage(String coverImagePath) {\n this.coverImagePath = coverImagePath;\n return this;\n }\n \n /**\n * \u0414\u043e\u0434\u0430\u0454 \u0444\u0430\u0439\u043b \u0434\u043e \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438.\n *\n * @param file \u0444\u0430\u0439\u043b \u0434\u043b\u044f \u0434\u043e\u0434\u0430\u0432\u0430\u043d\u043d\u044f\n * @return \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u0430 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430\n */\n public Audiobook addFile(AudiobookFile file) {\n if (file == null) {\n throw new IllegalArgumentException(\"\u0424\u0430\u0439\u043b \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 null\");\n }\n \n files.add(file);\n return this;\n }\n \n /**\n * \u041f\u043e\u0437\u043d\u0430\u0447\u0430\u0454 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443 \u044f\u043a \u043f\u0440\u043e\u0441\u043b\u0443\u0445\u0430\u043d\u0443 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0435\u043c.\n *\n * @param userId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n * @param eventPublisher \u043f\u0443\u0431\u043b\u0456\u043a\u0430\u0442\u043e\u0440 \u043f\u043e\u0434\u0456\u0439\n */\n public void markAsCompleted(UUID userId, DomainEventPublisher eventPublisher) {\n // \u041f\u0443\u0431\u043b\u0456\u043a\u0443\u0454\u043c\u043e \u043f\u043e\u0434\u0456\u044e \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u044f \u043f\u0440\u043e\u0441\u043b\u0443\u0445\u043e\u0432\u0443\u0432\u0430\u043d\u043d\u044f\n eventPublisher.publish(new AudiobookCompletedEvent(userId, id.getValue()));\n }\n \n /**\n * \u041f\u043e\u0432\u0435\u0440\u0442\u0430\u0454 \u0432\u0441\u0456 \u0444\u0430\u0439\u043b\u0438 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438.\n *\n * @return \u043d\u0435\u0437\u043c\u0456\u043d\u043d\u0438\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u0444\u0430\u0439\u043b\u0456\u0432\n */\n public List<AudiobookFile> getFiles() {\n return Collections.unmodifiableList(files);\n }\n \n private void validateTitle(String title) {\n if (title == null || title.trim().isEmpty()) {\n throw new IllegalArgumentException(\"\u041d\u0430\u0437\u0432\u0430 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u044c\u043e\u044e\");\n }\n \n if (title.length() > 255) {\n throw new IllegalArgumentException(\"\u041d\u0430\u0437\u0432\u0430 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0434\u043e\u0432\u0448\u043e\u044e \u0437\u0430 255 \u0441\u0438\u043c\u0432\u043e\u043b\u0456\u0432\");\n }\n }\n \n private void validateDuration(int duration) {\n if (duration <= 0) {\n throw new IllegalArgumentException(\"\u0422\u0440\u0438\u0432\u0430\u043b\u0456\u0441\u0442\u044c \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u043c\u0430\u0454 \u0431\u0443\u0442\u0438 \u0431\u0456\u043b\u044c\u0448\u043e\u044e \u0437\u0430 \u043d\u0443\u043b\u044c\");\n }\n }\n \n private void validateReleaseYear(int releaseYear) {\n int currentYear = java.time.Year.now().getValue();\n if (releaseYear < 1900 || releaseYear > currentYear + 1) {\n throw new IllegalArgumentException(\n \"\u0420\u0456\u043a \u0432\u0438\u043f\u0443\u0441\u043a\u0443 \u043c\u0430\u0454 \u0431\u0443\u0442\u0438 \u043c\u0456\u0436 1900 \u0442\u0430 \" + (currentYear + 1)\n );\n }\n }\n \n // \u0413\u0435\u0442\u0442\u0435\u0440\u0438\n public AudiobookId getId() {\n return id;\n }\n \n public AuthorId getAuthorId() {\n return authorId;\n }\n \n public GenreId getGenreId() {\n return genreId;\n }\n \n public String getTitle() {\n return title;\n }\n \n public int getDuration() {\n return duration;\n }\n \n public int getReleaseYear() {\n return releaseYear;\n }\n \n public String getDescription() {\n return description;\n }\n \n public String getCoverImagePath() {\n return coverImagePath;\n }\n \n @Override\n public boolean equals(Object o) {\n if (this == o) return true;\n if (o == null || getClass() != o.getClass()) return false;\n Audiobook audiobook = (Audiobook) o;\n return Objects.equals(id, audiobook.id);\n }\n \n @Override\n public int hashCode() {\n return Objects.hash(id);\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"### 8. Implement Aggregates with Proper Boundaries
