package com.arakviel.domain.model;

import com.arakviel.domain.enums.FileFormat;

import java.util.Objects;
import java.util.UUID;

/**
 * Об'єкт-значення, що представляє файл аудіокниги.
 */
public final class AudiobookFile {
 private final UUID id;
 private final String filePath;
 private final FileFormat format;
 private final int size;

 /**
 * Створює новий файл аудіокниги.
 *
 * @param filePath шлях до файлу
 * @param format формат файлу
 * @param size розмір файлу в байтах
 */
 public AudiobookFile(String filePath, FileFormat format, int size) {
 this(UUID.randomUUID(), filePath, format, size);
 }

 /**
 * Відновлює файл аудіокниги з існуючих даних.
 *
 * @param id ідентифікатор файлу
 * @param filePath шлях до файлу
 * @param format формат файлу
 * @param size розмір файлу в байтах
 */
 public AudiobookFile(UUID id, String filePath, FileFormat format, int size) {
 validateFilePath(filePath);
 validateSize(size);

 this.id = id;
 this.filePath = filePath;
 this.format = format;
 this.size = size;
 }

 private void validateFilePath(String filePath) {
 if (filePath == null || filePath.trim().isEmpty()) {
 throw new IllegalArgumentException("Шлях до файлу не може бути порожнім");
 }
 }

 private void validateSize(int size) {
 if (size <= 0) {
 throw new IllegalArgumentException("Розмір файлу має бути більшим за нуль");
 }
 }

 public UUID getId() {
 return id;
 }
