/**
 * Агрегат, що представляє аудіокнигу.
 * Інкапсулює бізнес-логіку та інваріанти, пов'язані з аудіокнигою.
 */
public class Audiobook {
 private final AudiobookId id;
 private final AuthorId authorId;
 private final GenreId genreId;
 private String title;
 private int duration;
 private int releaseYear;
 private String description;
 private String coverImagePath;
 private final List<AudiobookFile> files = new ArrayList<>();

 /**
 * Створює нову аудіокнигу.
 *
 * @param authorId ідентифікатор автора
 * @param genreId ідентифікатор жанру
 * @param title назва аудіокниги
 * @param duration тривалість у секундах
 * @param releaseYear рік випуску
 * @param description опис
 * @return нова аудіокнига
 */
 public static Audiobook create(
 AuthorId authorId,
 GenreId genreId,
 String title,
 int duration,
 int releaseYear,
 String description) {

 return new Audiobook(
 AudiobookId.generate(),
 authorId,
 genreId,
 title,
 duration,
 releaseYear,
 description,
 null
 );
 }

 /**
 * Відновлює аудіокнигу з існуючих даних.
