 * Містить бізнес-логіку та інваріанти, пов'язані з автором.
 */
public class Author {
 private final AuthorId id;
 private Name name;
 private String bio;
 private String imagePath;

 /**
 * Створює нового автора з унікальним ідентифікатором.
 *
 * @param firstName ім'я автора
 * @param lastName прізвище автора
 * @param bio біографія автора
 * @param imagePath шлях до зображення автора
 * @return новий екземпляр автора
 */
 public static Author create(String firstName, String lastName, String bio, String imagePath) {
 return new Author(AuthorId.generate(), new Name(firstName, lastName), bio, imagePath);
 }

 /**
 * Відновлює автора з існуючих даних (наприклад, з бази даних).
 *
 * @param id ідентифікатор автора
 * @param firstName ім'я автора
 * @param lastName прізвище автора
 * @param bio біографія автора
 * @param imagePath шлях до зображення автора
 * @return відновлений екземпляр автора
 */
 public static Author restore(UUID id, String firstName, String lastName, String bio, String imagePath) {
 return new Author(new AuthorId(id), new Name(firstName, lastName), bio, imagePath);
 }

 private Author(AuthorId id, Name name, String bio, String imagePath) {
 this.id = id;
 this.name = name;
 this.bio = bio;
 this.imagePath = imagePath;
 }

 /**
 * Оновлює інформацію про автора.
 *
 * @param firstName нове ім'я автора
 * @param lastName нове прізвище автора
 * @param bio нова біографія автора
 * @return оновлений екземпляр автора
 */
 public Author updateInfo(String firstName, String lastName, String bio) {
 this.name = new Name(firstName, lastName);
 this.bio = bio;
 return this;
 }

 /**
 * Оновлює шлях до зображення автора.
 *
 * @param imagePath новий шлях до зображення
 * @return оновлений екземпляр автора
 */
 public Author updateImage(String imagePath) {
 this.imagePath = imagePath;
 return this;
 }

 /**
 * Повертає повне ім'я автора.
 *
 * @return повне ім'я автора
 */
 public String getFullName() {
 return name.getFullName();
 }

 // Геттери
 public AuthorId getId() {
 return id;
 }
