CREATE TYPE IF NOT EXISTS file_format_enum AS ENUM ('mp3', 'ogg', 'wav', 'm4b', 'aac', 'flac');

-- 3NF - дані атомарні, залежать лише від первинного ключа
CREATE TABLE IF NOT EXISTS authors (
 PRIMARY KEY(id),
