 9	import org.springframework.stereotype.Repository;
 10	
 11	import java.sql.ResultSet;
 12	import java.util.List;
 13	import java.util.UUID;
 14	
 15	/**
 16	 * Реалізація репозиторію для специфічних операцій з авторами.
 17	 */
 18	@Repository
 19	public class AuthorRepositoryImpl extends GenericRepository<Author, UUID> implements AuthorRepository {
 20	
 21	 /**
 22	 * Конструктор репозиторію.
 23	 *
 24	 * @param connectionPool пул з'єднань до бази даних
 25	 */
 26	 public AuthorRepositoryImpl(ConnectionPool connectionPool) {
 27	 super(connectionPool, Author.class, "authors");
 28	 }
 29	
 30	 /**
 31	 * Пошук автора за ім’ям та прізвищем.
 32	 *
 33	 * @param firstName ім’я автора
 34	 * @param lastName прізвище автора
 35	 * @return список авторів
 36	 */
 37	 @Override
 38	 public List<Author> findByName(String firstName, String lastName) {
 39	 return findAll(
 40	 (whereClause, params) -> {
 41	 whereClause.add("first_name = ?");
 42	 whereClause.add("last_name = ?");
 43	 params.add(firstName);
 44	 params.add(lastName);
 45	 },
 46	 null, true, 0, Integer.MAX_VALUE
 47	 );
 48	 }
 49	
 50	 /**
 51	 * Пошук аудіокниг за ідентифікатором автора.
 52	 *
 53	 * @param authorId ідентифікатор автора
 54	 * @return список аудіокниг
 55	 */
 56	 @Override
 57	 public List<Audiobook> findAudiobooksByAuthorId(UUID authorId) {
 58	 String baseSql = "SELECT * FROM audiobooks WHERE author_id = ?";
 59	 return executeQuery(baseSql, stmt -> stmt.setObject(1, authorId), this::mapResultSetToAudiobook);
 60	 }
 61	
 62	 /**
 63	 * Пошук авторів за частковою відповідністю імені або прізвища.
 64	 *
 65	 * @param partialName часткове ім’я або прізвище
 66	 * @return список авторів
 67	 */
 68	 @Override
 69	 public List<Author> findByPartialName(String partialName) {
 70	 return findAll(
 71	 (whereClause, params) -> {
 72	 whereClause.add("(first_name ILIKE ? OR last_name ILIKE ?)");
 73	 params.add("%" + partialName + "%");
 74	 params.add("%" + partialName + "%");
 75	 },
 76	 null, true, 0, Integer.MAX_VALUE
 77	 );
 78	 }
 79	
 80	 /**
 81	 * Підрахунок аудіокниг для автора.
 82	 *
 83	 * @param authorId ідентифікатор автора
 84	 * @return кількість аудіокниг
 85	 */
 86	 @Override
 87	 public long countAudiobooksByAuthorId(UUID authorId) {
 88	 Filter filter = (whereClause, params) -> {
 89	 whereClause.add("author_id = ?");
 90	 params.add(authorId);
 91	 };
 92	 return count(filter, "audiobooks");
 93	 }
 94	
 95	 /**
 96	 * Зіставлення ResultSet у аудіокнигу.
 97	 *
 98	 * @param rs результат запиту
 99	 * @return аудіокнига
 100	 */
 101	 private Audiobook mapResultSetToAudiobook(ResultSet rs) {
 102	 try {
 103	 Audiobook audiobook = new Audiobook();
 104	 audiobook.setId(rs.getObject("id", UUID.class));
 105	 audiobook.setAuthorId(rs.getObject("author_id", UUID.class));
 106	 audiobook.setGenreId(rs.getObject("genre_id", UUID.class));
 107	 audiobook.setTitle(rs.getString("title"));
 108	 audiobook.setDuration(rs.getInt("duration"));
 109	 audiobook.setReleaseYear(rs.getInt("release_year"));
 110	 audiobook.setDescription(rs.getString("description"));
 111	 audiobook.setCoverImagePath(rs.getString("cover_image_path"));
 112	 return audiobook;
 113	 } catch (Exception e) {
 114	 throw new DatabaseAccessException("Помилка зіставлення ResultSet із аудіокнигою", e);
 115	 }
 116	 }
