 67	 // Arrange - create a new author with unique name
 68	 UUID authorId = UUID.randomUUID();
 69	 String uniqueFirstName = "UniqueFirst" + System.currentTimeMillis();
 70	 String uniqueLastName = "UniqueLast" + System.currentTimeMillis();
 71	 Author author = new Author(authorId, uniqueFirstName, uniqueLastName, "Bio", null);
