 118	
 119	 public static PoolConfig fromProperties(Properties properties) {
 120	 return new Builder()
 121	 .withUrl(properties.getProperty("db.url", DEFAULT_URL))
 122	 .withUser(properties.getProperty("db.username", DEFAULT_USER))
 123	 .withPassword(properties.getProperty("db.password", DEFAULT_PASSWORD))
 124	 .withMaxConnections(Integer.parseInt(properties.getProperty("db.pool.size", String.valueOf(DEFAULT_MAX_CONNECTIONS))))
 125	 .withAutoCommit(Boolean.parseBoolean(properties.getProperty("db.auto.commit", String.valueOf(DEFAULT_AUTO_COMMIT))))
 126	 .build();
 127	 }
 128	
 129	 public static class Builder {
 130	 private String url = DEFAULT_URL;
 131	 private String user = DEFAULT_USER;
 132	 private String password = DEFAULT_PASSWORD;
 133	 private int maxConnections = DEFAULT_MAX_CONNECTIONS;
 134	 private boolean autoCommit = DEFAULT_AUTO_COMMIT;
 135	
 136	 public Builder withUrl(String url) {
 137	 this.url = url;
 138	 return this;
 139	 }
 140	
 141	 public Builder withUser(String user) {
 142	 this.user = user;
 143	 return this;
 144	 }
 145	
 146	 public Builder withPassword(String password) {
 147	 this.password = password;
 148	 return this;
 149	 }
 150	
 151	 public Builder withMaxConnections(int maxConnections) {
 152	 this.maxConnections = Math.max(1, maxConnections);
 153	 return this;
 154	 }
 155	
 156	 public Builder withAutoCommit(boolean autoCommit) {
