 10	
 11	/**
 12	 * Сутність, що представляє автора аудіокниги.
 13	 */
 14	@Getter
 15	@Setter
 16	@NoArgsConstructor
 17	@AllArgsConstructor
 18	public class Author implements Comparable<Author> {
 19	
 20	 private UUID id;
 21	 private String firstName;
 22	 private String lastName;
 23	 private String bio;
 24	 private String imagePath;
 25	
 26	 @Override
 27	 public boolean equals(Object o) {
 28	 if (this == o) return true;
 29	 if (o == null || getClass() != o.getClass()) return false;
 30	 Author author = (Author) o;
 31	 return Objects.equals(id, author.id);
 32	 }
 33	
 34	 @Override
 35	 public int hashCode() {
 36	 return Objects.hash(id);
 37	 }
 38	
 39	 @Override
 40	 public int compareTo(Author other) {
 41	 // First compare by lastName
 42	 int lastNameComparison = this.lastName.compareToIgnoreCase(other.lastName);
 43	 if (lastNameComparison != 0) {
 44	 return lastNameComparison;
 45	 }
 46	
 47	 // If last names are equal, compare by firstName
 48	 return this.firstName.compareToIgnoreCase(other.firstName);
 49	 }
 50	}
