 14	/**
 15	 * Абстрактний клас для загальних операцій з базою даних.
 16	 *
 17	 * @param <T> тип сутності
 18	 * @param <ID> тип ідентифікатора сутності
 19	 */
 20	public abstract class GenericRepository<T, ID> implements Repository<T, ID> {
 21	
 22	 protected final ConnectionPool connectionPool;
 23	 protected final Class<T> entityClass;
 24	 protected final String tableName;
 25	
 26	 /**
 27	 * Конструктор репозиторію.
 28	 *
 29	 * @param connectionPool пул з'єднань до бази даних
 30	 * @param entityClass клас сутності
 31	 * @param tableName назва таблиці в базі даних
 32	 */
 33	 protected GenericRepository(ConnectionPool connectionPool, Class<T> entityClass, String tableName) {
 34	 this.connectionPool = connectionPool;
 35	 this.entityClass = entityClass;
 36	 this.tableName = tableName;
 37	 }
 38	
 39	
 40	 /**
 41	 * Пошук сутності за ідентифікатором.
 42	 *
 43	 * @param id ідентифікатор сутності
 44	 * @return Optional із знайденою сутністю або порожній, якщо не знайдено
 45	 */
 46	 @Override
 47	 public Optional<T> findById(ID id) {
 48	 return findByField("id", id).stream().findFirst();
 49	 }
 50	
 51	 /**
 52	 * Пошук сутностей за значенням поля.
 53	 *
 54	 * @param fieldName назва поля
 55	 * @param value значення поля
 56	 * @return список знайдених сутностей
 57	 */
 58	 @Override
 59	 public List<T> findByField(String fieldName, Object value) {
 60	 String sql = String.format("SELECT * FROM %s WHERE %s = ?", tableName, fieldName);
 61	 return executeQuery(sql, stmt -> stmt.setObject(1, value));
 62	 }
