 3	import lombok.*;
 4	
 5	import java.time.LocalDateTime;
 6	import java.util.Objects;
 7	import java.util.UUID;
 8	
 9	/**
 10	 * Сутність, що представляє прогрес прослуховування аудіокниги користувачем.
 11	 */
 12	@Getter
 13	@Setter
 14	@NoArgsConstructor
 15	@AllArgsConstructor
 16	public class ListeningProgress implements Comparable<ListeningProgress> {
 17	
 18	 @EqualsAndHashCode.Include
 19	 private UUID id;
 20	 private UUID userId;
 21	 private UUID audiobookId;
 22	 private int position;
 23	 private LocalDateTime lastListened;
 24	
 25	 @Override
 26	 public boolean equals(Object o) {
 27	 if (this == o) return true;
 28	 if (o == null || getClass() != o.getClass()) return false;
 29	 ListeningProgress that = (ListeningProgress) o;
 30	 return Objects.equals(id, that.id);
 31	 }
 32	
 33	 @Override
 34	 public int hashCode() {
 35	 return Objects.hash(id);
 36	 }
 37	
 38	 @Override
 39	 public int compareTo(ListeningProgress other) {
 40	 // First compare by lastListened (descending - newest first)
 41	 if (this.lastListened != null && other.lastListened != null) {
 42	 int timeComparison = other.lastListened.compareTo(this.lastListened);
 43	 if (timeComparison != 0) {
 44	 return timeComparison;
 45	 }
 46	 } else if (this.lastListened == null && other.lastListened != null) {
 47	 return 1; // Null values come after non-null values
 48	 } else if (this.lastListened != null && other.lastListened == null) {
 49	 return -1; // Non-null values come before null values
 50	 }
 51	
 52	 // If lastListened dates are equal or both null, compare by position (descending)
 53	 return Integer.compare(other.position, this.position);
 54	 }
 55	}
