 41	 // First compare by lastName
 42	 int lastNameComparison = this.lastName.compareToIgnoreCase(other.lastName);
 43	 if (lastNameComparison != 0) {
 44	 return lastNameComparison;
 45	 }
 46	
 47	 // If last names are equal, compare by firstName
 48	 return this.firstName.compareToIgnoreCase(other.firstName);
 49	 }
 50	}
