 53	 /**
 54	 * Пошук жанрів за ідентифікатором аудіокниги.
 55	 *
 56	 * @param audiobookId ідентифікатор аудіокниги
 57	 * @return список жанрів
 58	 */
 59	 @Override
 60	 public List<Genre> findByAudiobookId(UUID audiobookId) {
 61	 String baseSql = "SELECT g.* FROM genres g JOIN audiobooks a ON g.id = a.genre_id WHERE a.id = ?";
 62	 return executeQuery(baseSql, stmt -> stmt.setObject(1, audiobookId), this::mapResultSetToGenre);
 63	 }
