 146	 /**
 147	 * Валідує ім’я файлу, перевіряючи його розширення та коректність.
 148	 *
 149	 * @param fileName ім’я файлу
 150	 */
 151	 private void validateFileName(String fileName) {
 152	 if (fileName == null || fileName.trim().isEmpty()) {
 153	 throw new FileStorageException("Ім’я файлу не може бути порожнім");
 154	 }
 155	
 156	 String extension = getFileExtension(fileName).toLowerCase();
 157	 if (!allowedExtensions.contains(extension)) {
 158	 throw new FileStorageException("Непідтримуваний формат файлу: " + extension);
 159	 }
 160	
 161	 if (fileName.contains("..") || fileName.contains("/") || fileName.contains("\\")) {
 162	 throw new FileStorageException("Некоректне ім’я файлу: " + fileName);
 163	 }
 164	 }
