 346	 /**
 347	 * Виконує SQL-запит і повертає список сутностей.
 348	 *
 349	 * @param sql SQL-запит
 350	 * @param parameterSetter функція для встановлення параметрів
 351	 * @return список сутностей
 352	 */
 353	 protected List<T> executeQuery(String sql, ParameterSetter parameterSetter) {
 354	 try (Connection connection = connectionPool.getConnection();
 355	 PreparedStatement statement = connection.prepareStatement(sql)) {
 356	 parameterSetter.setParameters(statement);
 357	 try (ResultSet resultSet = statement.executeQuery()) {
 358	 List<T> entities = new ArrayList<>();
 359	 while (resultSet.next()) {
 360	 entities.add(mapResultSetToEntity(resultSet));
 361	 }
 362	 return entities;
 363	 }
 364	 } catch (SQLException e) {
 365	 throw new DatabaseAccessException("Помилка виконання запиту: " + sql, e);
 366	 }
 367	 }
